import numpy as np
from scipy.optimize import least_squares


def D(x):
    return np.c_[np.ones(len(x)), x]


def fit(F, y):
    return np.linalg.lstsq(F, y, rcond=1e-10)[0]


def cal(s, x):
    p = s['panel_a']
    F = D(p['u'])
    y = p['v']
    keep = np.ones(len(F), bool)
    for _ in range(8):
        c = fit(F[keep], y[keep])
        e = np.linalg.norm(F @ c - y, axis=1)
        keep = e < max(.001, 3 * np.median(e))
    return np.linalg.solve(c[1:].T, (x - c[0]).T).T, c, e


def AF(u):
    return D(np.c_[u, u * np.roll(u, -1, axis=1), u**3])


def coords(s, x):
    p = s['panel_a']
    u, v = p['u'], p['v']
    F = AF(u)
    _, _, e = cal(s, x)
    w = fit(F[e < 2], v[e < 2])
    z = np.linalg.solve(w[1:5].T, (x - w[0]).T).T
    for _ in range(12):
        J = np.broadcast_to(w[1:5], (len(z), 4, 4)).copy()
        K = w[5:9]
        rr = np.roll(z, -1, axis=1)
        J += rr[:, :, None] * K[None, :, :] + np.roll(z[:, :, None] * K[None, :, :], 1, axis=1) + 3 * z[:, :, None]**2 * w[None, 9:13, :]
        dz = np.linalg.solve(J.transpose(0, 2, 1), (AF(z) @ w - x)[..., None])[..., 0]
        z -= np.clip(dz, -.4, .4)
    return z


def kernel(x, degree, decay):
    dot = x @ x.T / x.shape[1]
    dist = np.maximum(np.diag(dot)[:, None] + np.diag(dot) - 2 * dot, 0)
    return (1 + dot)**degree + np.exp(-decay * dist)


def run_node(inputs: dict) -> dict:
    study = inputs['__input__']
    tr = study['train']
    z = coords(study, np.r_[tr['x'], study['test']['x']])
    p = study['panel_b']
    u, v = p['u'], p['v']

    def H(x, q):
        return D(np.sign(x) * np.maximum(abs(x) - q[0], 0)**q[1])

    def err(q):
        f = H(u, q)
        return (f @ fit(f, v) - v).ravel()

    q = least_squares(err, [.35, 1.5], bounds=([.15, .6], [.6, 2.5])).x
    b = H(z, q) @ fit(H(u, q), v)
    sym = np.c_[.3 * z + b, .3 * z - b]
    sep = np.c_[.3 * z, b]
    n = len(tr['x'])

    def head(design, degree, decay):
        k = kernel(design, degree, decay)
        return k[n:, :n] @ np.linalg.solve(k[:n, :n] + 1e-06 * np.eye(n), tr['y'])

    y = 0.5 * head(np.arcsinh(sym), 2, 1.4) + 0.5 * head(sym, 3, 0.15)
    return {'y_hat': y, 'trajectory_design': np.arcsinh(sep)}

