    T = study['train']['traj']

    def F(p):
        return -np.expm1(-t[:, None] * p)

    def err(p):
        f = F(p)
        return (f @ fit(f, T.T) - T.T).ravel()

    f = F(least_squares(err, [1.8, .42], bounds=([1., .15], [3., .85])).x)
    return {'basis': f, 'modes': fit(f, T.T).T}

